# GENERATED FILES ARE NO OVERLAP (2026-11-19 ~06:05Z: six movies changes from parallel refactoring lanes -- agreement,
# f2, datalayer3, resolver2-b1, enrichment2, resolver2 -- sat in single file, each `held: its check waits for <prev>`
# because each edits test/resources/coupling-baseline.tsv, several complexity- and length-baseline.tsv too: every
# coupling or complexity lane landed strictly one at a time, hours of serial checks). Those files are GENERATED (one
# row a class, package or method; `scripts/coupling-report --update`, `scripts/quality-report --update`), and the
# ratchets in the pre-push hook recompute them over the tree they check, so a combined tree's right content is "the
# rows regenerated over it" -- and two changes touching DISJOINT rows do not conflict at all. A repo registers them in
# red-repos.json (`generated`: {paths, regen: its own --update command, timeout}); a registered file is
# - NO OVERLAP: the hold (OVERLAPPING CHANGES ARE CHECKED AS ONE, queuebatch.py), backlog-batch membership, the conflict a
#   queued change is told of, `no longer applies on main` and the push's full-recheck rule all leave it out -- a
#   source both change (TestWiring.scala) still holds the younger (ONLY A VOIDED CHECK HOLDS, below);
# - RESOLVED, when a rebase, a batch's assembly or land's own rebase conflicts in it: its rows merged three-way (each
#   row keyed by its columns but the value: a row one side changed takes that side's value; disjoint rows always
#   merge), else -- a row both sides changed differently -- the repo's own regen command run in the tree, which IS
#   the combined tree at that commit (the other files picked), and its files staged into the commit being picked (on
#   the laptop: ci-runner's reconciler has no JVM, its checks run on CI, so there a same-row conflict is MAIN'S ROW,
#   below; the push's own rebase, under the landing lock, never runs one: a new verify round instead). The
#   commit keeps its message and trailers (a `Coupling:`/`Complexity:` rise still carries its own), and the hook's
#   ratchet judges the result as it judges any baseline; a member so resolved that its batch then fails is checked
#   alone (batch_alone), never rejected for it;
# - MAIN'S ROW, PROVISIONALLY, where no regen command runs (2026-11-19 06:58Z: lane F2b's queued change NOT LANDED --
#   "no longer applies on origin/main 2cfa0ee95e" -- because c3922ba26 had re-measured the very baseline rows its own
#   baseline commit changed, and ci-runner's reconciler, the server role, has no JVM: a rebase by hand and a new place
#   at the back of the queue, for a file no agent edits by hand): a row both sides changed keeps the side already in
#   the tree (main's, or the earlier batch members'), every other row merged as above; the files are named
#   (`provisional`) and the checks judge the combined tree -- the ratchet passes a fall not yet recorded and fails a
#   rise, naming the rows, and a failure is reported as the change's own with the regen command to run;
# - a SET table (a key on many lines: coupling-fanout-refs.tsv's `<class><TAB><target>`) is merged line by line;
# - else, the merge and the regen failing (a side not a table, the command's exit, its timeout), the member
#   is left out of the batch and checked alone (batch_alone `regen`, the files and why in the log), held as before
#   behind the change it overlaps. Tests: tests/test_generated.py, tests/test_queue_sim.py GeneratedOverlapTest.
GENERATED_REGEN_TIMEOUT = 1200  # s a generated file's regen command may run before the conflict is the author's ($AGENTCTL_GENERATED_REGEN_TIMEOUT)


_generated_slugs = process_cache({})  # repo path -> its GitHub slug (None: unknown)


def unmerged(wt):
    return git(wt, "diff", "--name-only", "--diff-filter=U", check=False).stdout.split()


def conflict_stages(wt, files):
    """{file: {1: base, 2: ours, 3: theirs}} of conflicted files, or None when one is added or deleted on one side."""
    stages = {}
    for f in files:
        got = {}
        for n in (1, 2, 3):
            r = git(wt, "show", f":{n}:{f}", check=False)
            if r.returncode != 0:  # added or deleted on one side: no merge of that
                return None
            got[n] = r.stdout
        stages[f] = got
    return stages


def generated_registry(repo: Optional[str]) -> List[Dict[str, Any]]:
    """The repo's registered generated files (red-repos.json `generated`, by the repo's GitHub slug): [] when none."""
    key = os.path.realpath(repo or ".")
    if key not in _generated_slugs:
        try:
            _generated_slugs[key] = slug(repo) if repo else None
        except (SystemExit, Exception):  # no remote, a path that is gone: nothing registered
            _generated_slugs[key] = None
    conf = red_repo_conf(_generated_slugs[key]) if _generated_slugs[key] else None
    return (conf or {}).get("generated") or []


def generated_entry(repo: Optional[str], path: str) -> Optional[Dict[str, Any]]:
    """The registry entry a path is generated by, or None."""
    return next((g for g in generated_registry(repo) if any(fnmatch.fnmatch(path, p) for p in g["paths"])), None)


def without_generated(repo: Optional[str], paths: List[str]) -> List[str]:
    """paths less the repo's registered generated files (GENERATED FILES ARE NO OVERLAP)."""
    reg = generated_registry(repo)
    return [p for p in paths if not reg or not generated_entry(repo, p)] if paths else paths


def without_derived(repo: Optional[str], paths: Optional[List[str]]) -> Optional[List[str]]:
    """paths less the repo's DERIVED files: regenerated over whatever tree they land in, never anyone's conflict, not
    even a change's checked alone (A DERIVED FILE HOLDS NOTHING)."""
    return [p for p in paths if not derived(generated_entry(repo, p))] if paths else paths


# ONLY A VOIDED CHECK HOLDS (2026-11-25: py-scalafix `held: its check waits for py-isolated (checking): both change
# docs/tools.md` -- a change checked alone, batch_alone, was judged strictly, every file it shares an overlap, the
# derived page too; and a generated file held a change behind a check in flight by default, unless its entry opted
# out with `holds: false`). A hold is worth having only where checking the younger now is a check thrown away: the
# two do not merge (it cannot land), a SOURCE both change (THE RULE rechecks it in full once the older lands:
# simulator invariant I9), or -- with the older already in flight, past the batch the two could have shared -- a
# generated file whose push round would void it: an entry DECLARED `order_sensitive: true`, in the one registry
# (red-repos.json `generated`) the hold, the batch's row merge and the regeneration all read. A derived file never is
# (regenerated over whatever tree it lands in, strict or not); movies declares its baselines, its measured tables
# and its snapshots (the queue simulator, 2026-11-25, the six baseline lanes of 2026-11-19 over 20 seeds: held, 40
# checks, landed in a mean 5.4 ticks, p90 7; unheld, 108 checks, 5.8, p90 9 -- the younger's check is voided by the
# older's landing and made again). So a new generated file is a registry row, and whether it holds is data on it.
def order_sensitive(repo: Optional[str], path: str) -> bool:
    """Whether path is a generated file of an entry declared ORDER-SENSITIVE (`order_sensitive: true`): both changes
    changing it holds the younger behind a check in flight (ONLY A VOIDED CHECK HOLDS)."""
    return bool((generated_entry(repo, path) or {}).get("order_sensitive"))


def table_parse(text, whole_line=False):
    """(header lines, [(key, line)]) of a generated table: `#` and blank lines head it, every other line a row keyed
    by all its tab-separated columns but the last (whole_line: by the whole line -- a SET table, one fact a line, like
    coupling-fanout-refs.tsv's `<class><TAB><target>`); None when a header line follows a row or a key repeats."""
    head, rows, keys = [], [], set()
    for line in text.splitlines(True):
        bare = line.rstrip("\n")
        if not bare.strip() or bare.startswith("#") or "\t" not in bare:
            if rows:
                return None
            head.append(line)
            continue
        key = bare if whole_line else bare.rsplit("\t", 1)[0]
        if key in keys:
            return None
        keys.add(key)
        rows.append((key, line if line.endswith("\n") else line + "\n"))
    return head, rows


def valued_table(text):
    """Whether a table has a VALUE column: a row whose last column is a number (a baseline's); a set table has none."""
    return any(re.fullmatch(r"-?\d+(\.\d+)?", line.rsplit("\t", 1)[-1].strip())
               for line in text.splitlines() if "\t" in line and not line.startswith("#"))


def three_way(b, o, t, prefer_ours=False):
    """The merged side of one value (b base, o ours, t theirs), or KeyError when both changed it differently (prefer_ours:
    then ours)."""
    if o == t or t == b:
        return o
    if o == b:
        return t
    if prefer_ours:
        return o
    raise KeyError


def rows_merge(base, ours, theirs, prefer_ours=False):
    """A generated table merged row by row (GENERATED FILES ARE NO OVERLAP): ours' order, theirs' added rows after the
    row they follow there; None when a row (or the header) changed on both sides differently (prefer_ours: then ours'
    row), or a side cannot be read as a table. A table whose keys repeat and that has no value column (valued_table)
    is read as a SET table (each line its own row: present or not, which never conflicts)."""
    parsed = [table_parse(x) for x in (base, ours, theirs)]
    if None in parsed and not any(valued_table(x) for x in (base, ours, theirs)):
        parsed = [table_parse(x, whole_line=True) for x in (base, ours, theirs)]
    if None in parsed:
        return None
    (bh, br), (oh, orow), (th, trow) = parsed
    try:
        head = three_way(bh, oh, th, prefer_ours)
        b, o, t = dict(br), dict(orow), dict(trow)
        merged = {k: three_way(b.get(k), o.get(k), t.get(k), prefer_ours) for k in set(b) | set(o) | set(t)}
    except KeyError:
        return None
    order = [k for k, _ in orow if merged.get(k) is not None]
    theirs_order = [k for k, _ in trow]
    for i, k in enumerate(theirs_order):
        if merged.get(k) is None or k in order:
            continue
        before = next((p for p in reversed(theirs_order[:i]) if p in order), None)
        order.insert(order.index(before) + 1 if before else 0, k)
    text = "".join(head) + "".join(merged[k] for k in order)
    return text if ours.endswith("\n") or not ours else text.rstrip("\n")


def regen_here() -> bool:
    """Whether this host runs every regen command of a repo, the heavy ones too: not the server role -- ci-runner's
    reconciler has no JVM (its checks run on CI), and a doomed sbt command would hold a tick step for minutes."""
    return host_role() != "server"


# A DERIVED FILE IS REGENERATED WHERE THE COMBINE HAPPENS (2026-11-23, the movies queue deadlocked at 22 changes:
# ci-runner, the server role, ran no regen command, so its queue held every change sharing docs/tools.md behind the
# one in flight -- the laptop's A DERIVED FILE HOLDS NOTHING (63239f5) never reached the host that runs the queue). A
# derived file's command is a cheap, deterministic script over the tree (`python3 scripts/tool_catalogue.py`, a path
# closure: no JVM, no network), so it runs on every role, the server included -- the interpreter agentctl runs under
# on PATH (run_regen) -- and a derived file holds nothing on any host. A snapshot's or a baseline's command (sbt) still
# runs only where regen_here says.
def regen_runs(g: Optional[Dict[str, Any]]) -> bool:
    """Whether registry entry g's regen command runs on this host: a DERIVED file's everywhere, the rest where
    regen_here."""
    return derived(g) or regen_here()


def regenerated_here(g: Optional[Dict[str, Any]]) -> bool:
    """Whether entry g is regenerated-only (a snapshot, a derived file) and its command runs on this host."""
    return regen_only(g) and regen_runs(g)


def regen_only(g: Optional[Dict[str, Any]]) -> bool:
    """Whether a registry entry is never merged by rows, always regenerated: a SNAPSHOT (`merge: regen`) or a DERIVED
    file (`merge: derived`)."""
    return bool(g) and g.get("merge") in ("regen", "derived")


def derived(g: Optional[Dict[str, Any]]) -> bool:
    """Whether a registry entry is a DERIVED file (`merge: derived`): regenerated over whatever tree it lands in, so it
    holds no change behind another (A DERIVED FILE HOLDS NOTHING, queuebatch.py)."""
    return bool(g) and g.get("merge") == "derived"


def explained(g: Optional[Dict[str, Any]]) -> bool:
    """Whether a regenerated entry's output must be explained by the sides: a SNAPSHOT's, never a DERIVED file's."""
    return bool(g) and g.get("merge") == "regen"


# A DERIVED FILE IS THE COMBINED TREE'S (2026-11-23: three parallel shell-to-Python migration lanes each regenerating
# movies' docs/tools.md -- `python3 scripts/tool_catalogue.py`, from each tool's own purpose line -- and every queued
# one conflicting with the others there; one lane was refused four times for that alone, a clean line merge or the
# docs union leaving a page scripts/tool_catalogue_test.py calls stale). A file the tree derives by a cheap,
# deterministic command -- a catalogue, a path closure -- is registered with `merge: derived`: regenerated over the
# combined tree whenever both sides changed it, as a snapshot is, but its output needs no explaining by the sides
# (explained): its aggregate lines -- a section's count, a "called by N tools" -- are by construction lines neither
# side had, and the repo's own check of the combined tree (the tool catalogue's test) asserts it. A file only PART of
# which is generated (`block`: [the begin line's prefix, the end line's]; .github/convergence-paths.txt's block) keeps
# its hand-written lines: they are merged three-way with the block left out (block_merge), a conflict there the
# author's, and the command then rewrites the block over the merged file.
def merge_file(ours: str, base: str, theirs: str, *flags: str) -> "subprocess.CompletedProcess[str]":
    """`git merge-file -p <flags>` of three texts: the CompletedProcess (returncode: the conflicts, < 0 or > 127 an
    error)."""
    import tempfile
    with tempfile.TemporaryDirectory() as td:
        paths = []
        for n, x in zip(("ours", "base", "theirs"), (ours, base, theirs)):
            q = os.path.join(td, n)
            with open(q, "w") as fh:
                fh.write(x)
            paths.append(q)
        return process_runner().run(["git", "merge-file", "-p", *flags, *paths], capture_output=True, text=True)


BLOCK_HELD = "agentctl: the generated block stands here\n"  # what stands in for a block while the lines around it are merged


def block_cut(text: str, block: List[str]) -> Optional[Tuple[List[str], List[str], List[str]]]:
    """(the lines before, the block's lines -- its begin and end lines with them --, the lines after) of a text, or
    None when it has no whole block."""
    lines = text.splitlines(True)
    begin = next((i for i, x in enumerate(lines) if x.startswith(block[0])), None)
    end = None if begin is None else next((i for i in range(begin + 1, len(lines)) if lines[i].startswith(block[1])),
                                          None)
    if end is None:
        return None
    return lines[:begin], lines[begin:end + 1], lines[end + 1:]


def block_merge(base: str, ours: str, theirs: str, block: List[str]) -> Optional[str]:
    """The file merged three-way outside its generated block, ours' block in place (for the regen command to
    rewrite), or None when a side has no whole block or the hand-written lines conflict."""
    cuts = [block_cut(x, block) for x in (base, ours, theirs)]
    if None in cuts:
        return None
    b, o, t = ("".join(c[0]) + BLOCK_HELD + "".join(c[2]) for c in cuts)
    r = merge_file(o, b, t)
    if r.returncode != 0 or r.stdout.count(BLOCK_HELD) != 1:
        return None
    return r.stdout.replace(BLOCK_HELD, "".join(cuts[1][1]))


# SNAPSHOTS ARE REGENERATED, NEVER MERGED (2026-11-21 ~07:40Z: split-shared-js `held: its check waits for scrapers-2`,
# both changing movies' page snapshots expected-{index,warszawa-index,wroclaw-index}.html -- files PageSnapshotSpec
# writes, which no agent edits by hand). A snapshot -- rendered HTML, a JSON read model, a whole-corpus text -- has no
# rows: a three-way merge of its lines, git's or ours, is a guess at what the combined code renders. Registered with
# `merge: regen`, it is no overlap (like every generated file), and whenever BOTH sides changed it -- a conflict, or a
# clean textual merge of two edits -- its regen command runs over the combined tree and its output is what the batch
# checks. A REGENERATED SNAPSHOT HIDES NOTHING: its output must be EXPLAINED by the two sides -- every line it adds
# added by one of them, every line it drops dropped by one of them (snapshot_unexplained) -- or the resolution fails
# and the member is held as before: an interaction neither side committed (a line only the combined code renders) is
# never landed by a regenerator; its author regenerates and commits it. Where no regen command runs (the server role)
# a snapshot is never kept provisionally: held. Then the batch's checks run over the combined tree as over any other
# (movies: FilmScheduleEndToEnd asserts expected-schedules.txt and the read model; PageSnapshotSpec runs on Main).
def snapshot_unexplained(base, ours, theirs, regenerated):
    """The first line of a regenerated snapshot neither side explains (added by neither, or dropped by neither), as
    `+line` / `-line`; None when each of its changes against the base is one of the sides' own."""
    from collections import Counter
    b, o, t, r = (Counter(x.splitlines()) for x in (base, ours, theirs, regenerated))
    added, removed = r - b, b - r
    may_add, may_remove = (o - b) | (t - b), (b - o) | (b - t)
    for line, n in added.items():
        if n > may_add.get(line, 0):
            return "+" + line[:160]
    for line, n in removed.items():
        if n > may_remove.get(line, 0):
            return "-" + line[:160]
    return None


def regen_env():
    """tool_env with the interpreter agentctl runs under last on PATH: a derived file's `python3 <script>` runs on a host
    whose PATH has no python3 of its own (ci-runner's reconciler: python3 by its store path; REGENERATED WHERE THE
    COMBINE HAPPENS)."""
    env = tool_env()
    here = os.path.dirname(sys.executable)
    if here and here not in env.get("PATH", "").split(":"):
        env["PATH"] = ":".join(x for x in (env.get("PATH", ""), here) if x)
    return env


def run_regen(wt, g):
    """Run registry entry g's regen command in wt: None, or why it failed, in words."""
    limit = g.get("timeout") or env_num("AGENTCTL_GENERATED_REGEN_TIMEOUT", GENERATED_REGEN_TIMEOUT)
    cmd = " ".join(shlex.quote(x) for x in g["regen"])
    try:
        r = process_runner().run(g["regen"], cwd=wt, capture_output=True, text=True, timeout=limit, env=regen_env(),
                           stdin=subprocess.DEVNULL)
    except subprocess.TimeoutExpired:
        return f"`{cmd}` ran past {limit:.0f} s"
    except OSError as ex:
        return f"`{cmd}` could not run ({ex.strerror or ex})"
    if r.returncode != 0:
        last = ((r.stderr or r.stdout or "").strip().splitlines() or [""])[-1][:200]
        return f"`{cmd}` exited {r.returncode}" + (f": {last}" if last else "")
    return None


def regenerate(wt, files, regenerated=None, provisional=None, sides=None):
    """Resolve wt's conflicted generated files over the tree as it stands (the combined tree): each merged row by row,
    else its registry entry's regen command run in wt and its files staged -- or, where no regen command runs (the
    server role), merged row by row keeping the tree's (ours: main's) side of a row both sides changed, the file named
    in `provisional` (MAIN'S ROW, PROVISIONALLY). A SNAPSHOT (`merge: regen`) is never merged by rows: regenerated, its
    output explained by the sides (SNAPSHOTS ARE REGENERATED, NEVER MERGED), or not resolved. `sides`: {file: {1: base,
    2: ours, 3: theirs}} of files both sides changed that git merged cleanly (a snapshot's, regenerated all the same);
    else the conflict's stages. None: resolved (staged, appended to `regenerated`); else why not, in words."""
    stages = sides if sides is not None else conflict_stages(wt, files)
    if stages is None:
        return "added or deleted on one side"
    pending = []

    def take(f, text):
        with open(os.path.join(wt, f), "w") as fh:
            fh.write(text)
        git(wt, "add", "--", f)
    for f in files:
        text = None if regen_only(generated_entry(wt, f)) else rows_merge(stages[f][1], stages[f][2], stages[f][3])
        if text is None:
            pending.append(f)
            continue
        take(f, text)
    for g in generated_registry(wt):  # one run of each command, however many of its files conflict
        mine = [f for f in pending if generated_entry(wt, f) is g]
        if not mine:
            continue
        if not g.get("regen"):  # a hand-written table merged row by row only: never a side's row kept provisionally
            return f"a row both sides changed in {', '.join(mine)}, which no regen command decides"
        if not regen_runs(g):
            if regen_only(g):
                return f"{', '.join(mine)}: a snapshot both sides changed, and the server role runs no regen command"
            for f in mine:
                text = rows_merge(stages[f][1], stages[f][2], stages[f][3], prefer_ours=True)
                if text is None:
                    return f"{f} cannot be read as a table, and the server role runs no regen command"
                take(f, text)
                if provisional is not None:
                    provisional.append(f)
            continue
        if sides is None:  # no conflict markers in what the command reads
            why = regen_base(wt, g, mine, stages, take)
            if why:
                return why
        before = {p: git(wt, "show", f":{p}", check=False).stdout for p in tracked(wt, g["paths"])
                  if p not in mine} if explained(g) else {}
        why = run_regen(wt, g)
        if why:
            return ("both sides changed the snapshot " if explained(g) else "both sides changed the derived file "
                    if regen_only(g) else "a row both sides changed, and ") + why
        why = snapshot_hidden(wt, g, mine, stages, before) if explained(g) else None
        if why:
            return why
        git(wt, "add", "-A", "--", *g["paths"], check=False)
        left = sorted(set(unmerged(wt)) & set(mine))
        if left:
            return f"`{' '.join(g['regen'])}` left {', '.join(left)} unresolved"
        stray = git(wt, "diff", "--name-only", check=False).stdout.split()  # what else it wrote: never picked along
        if stray:
            git(wt, "checkout", "--", *stray, check=False)
    if regenerated is not None:
        regenerated.extend(f for f in files if f not in regenerated)
    return None


def snapshot_hidden(wt: str, g: Dict[str, Any], mine: List[str], stages: Dict[str, Dict[int, str]],
                    before: Dict[str, str]) -> Optional[str]:
    """Why a snapshot regenerated in wt is no resolution -- a file not written, a change neither side made, another
    snapshot of the command moved (A REGENERATED SNAPSHOT HIDES NOTHING) --, or None."""
    for f in mine:
        path = os.path.join(wt, f)
        if not os.path.exists(path):
            return f"`{' '.join(g['regen'])}` did not write {f}"
        with open(path) as fh:
            odd = snapshot_unexplained(stages[f][1], stages[f][2], stages[f][3], fh.read())
        if odd:
            return (f"the regenerated {f} holds a change neither side made ({odd}): an interaction its "
                    "authors regenerate and commit")
    for p, text in before.items():
        path = os.path.join(wt, p)
        if os.path.exists(path) and open(path).read() != text:
            return (f"the regen also moved {p}, which only one side changed: an interaction its authors "
                    "regenerate and commit")
    return None


def regen_base(wt: str, g: Dict[str, Any], mine: List[str], stages: Dict[str, Dict[int, str]],
               take: Callable[[str, str], None]) -> Optional[str]:
    """Put wt's conflicted files of entry g in a state its regen command reads: ours' side, or -- a file with a
    generated `block` -- its hand-written lines merged (A DERIVED FILE IS THE COMBINED TREE'S). None, or why not."""
    if not g.get("block"):
        git(wt, "checkout", "--ours", "--", *mine, check=False)
        return None
    for f in mine:
        text = block_merge(stages[f][1], stages[f][2], stages[f][3], g["block"])
        if text is None:
            return f"{f}: both sides changed its hand-written lines, outside the generated block, in one place"
        take(f, text)
    return None


def regen_owed(wt: str, base: str, moved: str, head: Optional[str]) -> List[str]:
    """The files a push of the change moved..head (rebased by git alone onto main, which moved base..moved) owes a
    regeneration of: the regenerated-only ones (a snapshot, a DERIVED file) both main's move and the change change --
    git's line merge of them, clean or not, is no tree's output (A DERIVED FILE HOLDS NOTHING, queuebatch.py) -- those
    whose command runs here (regen_runs: a derived file's on every role)."""
    if not head:
        return []
    names = [set(git(wt, "diff", "--name-only", "--no-renames", a, b, check=False).stdout.split())
             for a, b in ((base, moved), (moved, head))]
    return sorted(f for f in names[0] & names[1] if regenerated_here(generated_entry(wt, f)))


def tracked(wt, globs):
    """The tracked paths of wt's index matching globs."""
    out = git(wt, "ls-files", "--", *globs, check=False).stdout.split()
    return [p for p in out if any(fnmatch.fnmatch(p, g) for g in globs)]


def snapshots_both_changed(wt, commit, before):
    """{file: {1: base, 2: ours, 3: theirs}} of the SNAPSHOTS (`merge: regen`) commit changes which the tree had changed
    too since commit's parent (before: the tree's HEAD before the pick) -- git merged them cleanly, and a snapshot is
    regenerated all the same (SNAPSHOTS ARE REGENERATED, NEVER MERGED)."""
    reg = [g for g in generated_registry(wt) if regenerated_here(g)]
    if not reg:
        return {}
    mine = git(wt, "diff-tree", "--no-commit-id", "--name-only", "-r", commit, check=False).stdout.split()
    out = {}
    for f in mine:
        if not any(generated_entry(wt, f) is g for g in reg):
            continue
        if git(wt, "diff", "--quiet", f"{commit}^", before, "--", f, check=False).returncode == 0:
            continue  # only this side changed it: its own regenerated snapshot stands
        got = {n: git(wt, "show", f"{ref}:{f}", check=False) for n, ref in ((1, f"{commit}^"), (2, before), (3, commit))}
        if any(r.returncode != 0 for r in got.values()):
            continue  # added or deleted on a side: git's pick decided it
        out[f] = {n: r.stdout for n, r in got.items()}
    return out
